-- 105_immutable_historical_project_record.sql
BEGIN;
CREATE TABLE IF NOT EXISTS public.historical_project_records(id uuid PRIMARY KEY,project_id bigint NOT NULL UNIQUE REFERENCES public.projects(id)ON DELETE RESTRICT,record_version integer NOT NULL DEFAULT 1 CHECK(record_version=1),ontology_version_id uuid REFERENCES public.work_ontology_versions(id)ON DELETE RESTRICT,payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object'),payload_hash text NOT NULL CHECK(char_length(payload_hash)=32),sealed_by uuid NOT NULL REFERENCES auth.users(id)ON DELETE RESTRICT,sealed_at timestamptz NOT NULL DEFAULT now());CREATE OR REPLACE FUNCTION private.prevent_historical_record_mutation()RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN RAISE EXCEPTION'HISTORICAL_PROJECT_RECORD_IMMUTABLE'USING ERRCODE='55000';END;$$;DROP TRIGGER IF EXISTS historical_project_record_immutable ON public.historical_project_records;CREATE TRIGGER historical_project_record_immutable BEFORE UPDATE OR DELETE ON public.historical_project_records FOR EACH ROW EXECUTE FUNCTION private.prevent_historical_record_mutation();ALTER TABLE public.historical_project_records ENABLE ROW LEVEL SECURITY;DROP POLICY IF EXISTS historical_project_record_select ON public.historical_project_records;CREATE POLICY historical_project_record_select ON public.historical_project_records FOR SELECT TO authenticated USING(public.can_access_project(project_id));REVOKE ALL ON TABLE public.historical_project_records FROM PUBLIC,anon,authenticated,service_role;GRANT SELECT ON TABLE public.historical_project_records TO authenticated;
CREATE OR REPLACE FUNCTION public.seal_historical_project_record(p_project_id bigint,p_record_id uuid,p_client_request_id uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE u uuid:=auth.uid();role_name text;req public.write_command_requests%ROWTYPE;pr public.projects%ROWTYPE;body jsonb;hash text;result jsonb;BEGIN SELECT upper(role)INTO role_name FROM public.profiles WHERE id=u;IF u IS NULL OR role_name NOT IN('PM','ADMIN')OR public.can_write_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION'HISTORICAL_PROJECT_RECORD_FORBIDDEN'USING ERRCODE='42501';END IF;IF p_record_id IS NULL OR p_client_request_id IS NULL THEN RAISE EXCEPTION'INVALID_HISTORICAL_PROJECT_RECORD_COMMAND'USING ERRCODE='22023';END IF;INSERT INTO public.write_command_requests(actor_id,operation,client_request_id,project_id)VALUES(u,'project_closeout.history.seal',p_client_request_id,p_project_id)ON CONFLICT(actor_id,operation,client_request_id)DO NOTHING;SELECT*INTO req FROM public.write_command_requests WHERE actor_id=u AND operation='project_closeout.history.seal'AND client_request_id=p_client_request_id;IF req.response IS NOT NULL THEN RETURN req.response||jsonb_build_object('idempotentReplay',true);END IF;IF EXISTS(SELECT 1 FROM public.historical_project_records WHERE project_id=p_project_id)THEN RAISE EXCEPTION'HISTORICAL_PROJECT_RECORD_ALREADY_SEALED'USING ERRCODE='55000';END IF;IF NOT(EXISTS(SELECT 1 FROM public.project_cost_closeout_versions WHERE project_id=p_project_id AND status='CONFIRMED')AND EXISTS(SELECT 1 FROM public.project_schedule_closeout_versions WHERE project_id=p_project_id AND status='CONFIRMED')AND EXISTS(SELECT 1 FROM public.project_scope_closeout_versions WHERE project_id=p_project_id AND status='CONFIRMED')AND EXISTS(SELECT 1 FROM public.project_quality_closeout_versions WHERE project_id=p_project_id AND status='CONFIRMED')AND EXISTS(SELECT 1 FROM public.project_variation_closeout_versions WHERE project_id=p_project_id AND status='CONFIRMED')AND EXISTS(SELECT 1 FROM public.project_payment_closeout_versions WHERE project_id=p_project_id AND status='CONFIRMED')AND EXISTS(SELECT 1 FROM public.project_lessons_learned_versions WHERE project_id=p_project_id AND status='CONFIRMED')AND EXISTS(SELECT 1 FROM public.project_contractor_scorecards WHERE project_id=p_project_id AND status='CONFIRMED'))THEN RAISE EXCEPTION'HISTORICAL_RECORD_REQUIRES_ALL_CONFIRMED_CLOSEOUTS'USING ERRCODE='55000';END IF;SELECT*INTO pr FROM public.projects WHERE id=p_project_id;
body:=jsonb_build_object('schemaVersion',1,'project',to_jsonb(pr)-'created_by','cost',(SELECT to_jsonb(x)-'created_by'FROM public.project_cost_closeout_versions x WHERE project_id=p_project_id AND status='CONFIRMED'),'schedule',(SELECT to_jsonb(x)-'created_by'FROM public.project_schedule_closeout_versions x WHERE project_id=p_project_id AND status='CONFIRMED'),'scope',(SELECT to_jsonb(x)-'created_by'FROM public.project_scope_closeout_versions x WHERE project_id=p_project_id AND status='CONFIRMED'),'quality',(SELECT to_jsonb(x)-'created_by'FROM public.project_quality_closeout_versions x WHERE project_id=p_project_id AND status='CONFIRMED'),'variations',(SELECT to_jsonb(x)-'created_by'FROM public.project_variation_closeout_versions x WHERE project_id=p_project_id AND status='CONFIRMED'),'payments',(SELECT to_jsonb(x)-'created_by'FROM public.project_payment_closeout_versions x WHERE project_id=p_project_id AND status='CONFIRMED'),'lessons',(SELECT to_jsonb(x)-'created_by'FROM public.project_lessons_learned_versions x WHERE project_id=p_project_id AND status='CONFIRMED'),'contractorScorecard',(SELECT to_jsonb(x)-'created_by'FROM public.project_contractor_scorecards x WHERE project_id=p_project_id AND status='CONFIRMED'));hash:=md5(body::text);INSERT INTO public.historical_project_records VALUES(p_record_id,p_project_id,1,pr.work_ontology_version_id,body,hash,u,now());result:=jsonb_build_object('recordId',p_record_id,'projectId',p_project_id,'recordVersion',1,'payloadHash',hash,'sealedAt',now());UPDATE public.write_command_requests SET response=result,completed_at=now()WHERE id=req.id;RETURN result||jsonb_build_object('idempotentReplay',false);END;$$;
CREATE OR REPLACE FUNCTION public.get_historical_project_record(p_project_id bigint)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$DECLARE x public.historical_project_records%ROWTYPE;BEGIN IF auth.uid()IS NULL OR public.can_access_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION'HISTORICAL_PROJECT_RECORD_FORBIDDEN'USING ERRCODE='42501';END IF;SELECT*INTO x FROM public.historical_project_records WHERE project_id=p_project_id;RETURN jsonb_build_object('projectId',p_project_id,'isSealed',x.id IS NOT NULL,'record',CASE WHEN x.id IS NULL THEN NULL ELSE jsonb_build_object('recordId',x.id,'recordVersion',x.record_version,'ontologyVersionId',x.ontology_version_id,'payload',x.payload,'payloadHash',x.payload_hash,'sealedAt',x.sealed_at)END);END;$$;REVOKE ALL ON FUNCTION private.prevent_historical_record_mutation()FROM PUBLIC,anon,authenticated,service_role;REVOKE ALL ON FUNCTION public.seal_historical_project_record(bigint,uuid,uuid),public.get_historical_project_record(bigint)FROM PUBLIC,anon,authenticated,service_role;GRANT EXECUTE ON FUNCTION public.seal_historical_project_record(bigint,uuid,uuid),public.get_historical_project_record(bigint)TO authenticated;COMMIT;
